mapper.select:
select 
    from p_application a where a.account_id=#{accountId} and a.purpose='USER' and a.status!='DELETED'
      and (#{status} is null or a.status=#{status}) order by a.created_at desc,a.id desc limit #{limit} offset #{offset}

mapper.update:
update p_application set name=#{name},description=#{description},avatar_id=#{avatarId},
    voice_id=#{voiceId},system_prompt=#{systemPrompt},revision=revision+1,updated_at=utc_timestamp(3)
    where id=#{applicationId} and revision=#{expectedRevision}
